20	/// Serves packages from standard locations.
21	///
22	/// In order of priority, this tries to obtain a package from
23	///
24	/// - a package data directory (that is intended for system-wide storage of user
25	///   packages)
26	/// - a package cache directory (that is intended for caching of automatically
27	///   downloaded packages)
28	/// - by downloading it from Typst Universe or a mirror of it (if it's namespace
29	///   matches the one Typst Universe serves)
30	///
31	/// With default configuration, this loads packages from the same sources as the
32	/// CLI.
33	#[cfg(feature = "system-packages")]
34	#[derive(Debug)]
35	pub struct SystemPackages {
36	    data: Option<FsPackages>,
37	    cache: Option<FsPackages>,
38	    universe: UniversePackages,
39	}
40	
41	#[cfg(feature = "system-packages")]
42	impl SystemPackages {
43	    /// Creates a new handle that serves packages from standard
44	    /// environment-defined directories and the official Typst Universe
45	    /// registry.
46	    ///
47	    /// - See [`FsPackages`] for more details on the default directories.
48	    /// - See [`UniversePackages`] for more details on the registry.
49	    ///
50	    /// This loads packages from the same sources as the CLI in its default
51	    /// configuration.
52	    pub fn new(downloader: impl Downloader) -> Self {
53	        Self::from_parts(
54	            FsPackages::system_data(),
55	            FsPackages::system_cache(),
56	            UniversePackages::new(downloader),
57	        )
58	    }
59	
60	    /// Creates a new system package loader from custom configured parts.
61	    pub fn from_parts(
62	        data: Option<FsPackages>,
63	        cache: Option<FsPackages>,
64	        universe: UniversePackages,
65	    ) -> Self {
66	        Self { data, cache, universe }
67	    }
68	
69	    /// Returns a handle to the data package directory.
70	    pub fn data(&self) -> Option<&FsPackages> {
71	        self.data.as_ref()
72	    }
73	
74	    /// Returns a handle to the cache package directory.
75	    pub fn cache(&self) -> Option<&FsPackages> {
76	        self.cache.as_ref()
77	    }
78	
79	    /// Returns a handle to the Typst universe registry.
80	    pub fn universe(&self) -> &UniversePackages {
81	        &self.universe
82	    }
83	
84	    /// Returns the file system root from which the given package's content can
85	    /// be loaded.
86	    ///
87	    /// May download the package from the network if it's not already available.
88	    /// Downloads are retained in the configured cache directory. As such, this
89	    /// function can have a file system side effect.
90	    ///
91	    /// Concurrent downloads do not cause corruption, but for the purpose of
92	    /// efficiency, it may be desirable to avoid them. If you use the
93	    /// [`FileStore`](crate::files::FileStore), this is already the case since
94	    /// it acquires a lock during file loading.
95	    pub fn obtain(&self, spec: &PackageSpec) -> PackageResult<FsRoot> {
96	        if let Some(packages) = &self.data
97	            && let Some(root) = packages.obtain(spec)
98	        {
99	            return Ok(root);
100	        }
101	
102	        if let Some(cache) = &self.cache {
103	            if let Some(root) = cache.obtain(spec) {
104	                return Ok(root);
105	            }
106	
107	            // Download from network if it doesn't exist yet.
108	            if spec.namespace == UniversePackages::NAMESPACE {
109	                let mut archive = self.universe.package(spec)?;
110	
111	                cache.store(spec, |tempdir| {
112	                    archive.unpack(tempdir).map_err(|err| {
113	                        PackageError::MalformedArchive(Some(eco_format!("{err}")))
114	                    })
115	                })?;
116	
117	                if let Some(root) = cache.obtain(spec) {
118	                    return Ok(root);
119	                }
120	            }
121	        }
122	
123	        Err(PackageError::NotFound(spec.clone()))
124	    }
125	
126	    /// Tries to determine the latest version of a package.
127	    pub fn latest_version(
128	        &self,
129	        spec: &VersionlessPackageSpec,
130	    ) -> StrResult<PackageVersion> {
131	        if spec.namespace == UniversePackages::NAMESPACE {
132	            self.universe.latest_version(spec)
133	        } else {
134	            // For other namespaces, search locally. We only search in the data
135	            // directory and not the cache directory, because the latter is not
136	            // intended for storage of local packages.
137	            self.data
138	                .as_ref()
139	                .and_then(|pkgs| pkgs.latest_version(spec))
140	                .ok_or_else(|| eco_format!("please specify the desired version"))
141	        }
142	    }
143	}
144	
145	/// Serves packages from a well-structured directory on the file system.
146	///
147	/// This directory should be structured as follows:
148	/// - Top-level directories denote namespaces
149	/// - Second-level directories denote packages
150	/// - Third-level directories denote package versions
151	#[derive(Debug, Clone)]
152	pub struct FsPackages(PathBuf);
153	
154	impl FsPackages {
155	    /// Creates a new handle that serves packages from the given directory.
156	    pub fn new(path: impl Into<PathBuf>) -> Self {
157	        Self(path.into())
158	    }
159	
160	    /// Tries to provide a handle to the environment-defined standard system
161	    /// package data directory.
162	    ///
163	    /// This is:
164	    /// - `$XDG_DATA_HOME/typst/packages` or `~/.local/share/typst/packages` on Linux
165	    /// - `~/Library/Application Support/typst/packages` on macOS
166	    /// - `%APPDATA%/typst/packages` on Windows
167	    #[cfg(feature = "system-packages")]
168	    pub fn system_data() -> Option<FsPackages> {
169	        dirs::data_dir().map(|dir| FsPackages::new(dir.join("typst").join("packages")))
170	    }
171	
172	    /// Tries to provide a handle to the environment-defined standard system
173	    /// package cache directory.
174	    ///
175	    /// This is:
176	    /// - `$XDG_CACHE_HOME/typst/packages` or `~/.cache/typst/packages` on Linux
177	    /// - `~/Library/Caches/typst/packages` on macOS
178	    /// - `%LOCALAPPDATA%/typst/packages` on Windows
179	    #[cfg(feature = "system-packages")]
180	    pub fn system_cache() -> Option<FsPackages> {
181	        dirs::cache_dir().map(|dir| FsPackages::new(dir.join("typst").join("packages")))
182	    }
183	
184	    /// Returns the path from which this serves packages.
185	    pub fn path(&self) -> &Path {
186	        &self.0
187	    }
188	
189	    /// Returns the file system root from which the given package's content can
190	    /// be loaded.
191	    pub fn obtain(&self, spec: &PackageSpec) -> Option<FsRoot> {
192	        let dir = self
193	            .path()
194	            .join(spec.namespace.as_str())
195	            .join(spec.name.as_str())
196	            .join(spec.version.to_string());
197	        dir.exists().then_some(FsRoot::new(dir))
198	    }
199	
200	    /// Tries to determine the latest version of a particular package in the
201	    /// directory tree.
202	    pub fn latest_version(
203	        &self,
204	        spec: &VersionlessPackageSpec,
205	    ) -> Option<PackageVersion> {
206	        // For other namespaces, search locally. We only search in the data
207	        // directory and not the cache directory, because the latter is not
208	        // intended for storage of local packages.
209	        let dir = self.path().join(spec.namespace.as_str()).join(spec.name.as_str());
210	        std::fs::read_dir(dir)
211	            .into_iter()
212	            .flatten()
213	            .filter_map(|entry| entry.ok())
214	            .map(|entry| entry.path())
215	            .filter_map(|path| path.file_name()?.to_string_lossy().parse().ok())
216	            .max()
217	    }
218	
219	    /// Stores data for the given package in the package directory by invoking
220	    /// `write` on a target path. The package contents should be written
221	    /// relative to the path passed to `write`.
222	    ///
223	    /// Internally, this function ensures that concurrent access to the package
224	    /// directory is safe. From two concurrent stores, it is not specified which
225	    /// one wins, but they will not infer or result in partial / corrupted
226	    /// package contents.
227	    #[cfg(feature = "universe-packages")]
228	    pub fn store(
229	        &self,
230	        spec: &PackageSpec,
231	        write: impl FnOnce(&Path) -> PackageResult<()>,
232	    ) -> PackageResult<()> {
233	        let error = |message: &str, err: std::io::Error| -> PackageError {
234	            PackageError::Other(Some(eco_format!("{message}: {err}")))
235	        };
236	
237	        // The directory in which the package's version lives.
238	        let base_dir = self.path().join(spec.namespace.as_str()).join(spec.name.as_str());
239	
240	        // The place at which the specific package version will live in the end.
241	        let package_dir = base_dir.join(spec.version.to_string());
242	
243	        // To prevent multiple Typst instances from interfering, we download
244	        // into a temporary directory first and then move this directory to
245	        // its final destination.
246	        //
247	        // In the `rename` function's documentation it is stated:
248	        // > This will not work if the new name is on a different mount point.
249	        //
250	        // By locating the temporary directory directly next to where the
251	        // package directory will live, we are (trying our best) making sure
252	        // that `tempdir` and `package_dir` are on the same mount point.
253	        let tempdir = Tempdir::create(base_dir.join(format!(
254	            ".tmp-{}-{}",
255	            spec.version,
256	            fastrand::u32(..),
257	        )))
258	        .map_err(|err| error("failed to create temporary package directory", err))?;
259	
260	        // Non-atomically write the package contents into the temporary
261	        // directory.
262	        write(tempdir.as_ref())?;
263	
264	        // When trying to move (i.e., `rename`) the directory from one place to
265	        // another and the target/destination directory is empty, then the
266	        // operation will succeed (if it's atomic, or hardware doesn't fail, or
267	        // power doesn't go off, etc.). If however the target directory is not
268	        // empty, i.e., another instance already successfully moved the package,
269	        // then we can safely ignore the `DirectoryNotEmpty` error.
270	        //
271	        // This means that we do not check the integrity of an existing moved
272	        // package, just like we don't check the integrity if the package
273	        // directory already existed in the first place. If situations with
274	        // broken packages still occur even with the rename safeguard, we might
275	        // consider more complex solutions like file locking or checksums.
276	        match std::fs::rename(&tempdir, &package_dir) {
277	            Ok(()) => Ok(()),
278	            Err(err) if err.kind() == std::io::ErrorKind::DirectoryNotEmpty => Ok(()),
279	            Err(err) => Err(error("failed to move downloaded package directory", err)),
280	        }
281	    }
282	}
283	
284	/// A temporary directory that is automatically cleaned up.
285	#[cfg(feature = "universe-packages")]
286	#[derive(Debug)]
287	struct Tempdir(PathBuf);
288	
289	#[cfg(feature = "universe-packages")]
290	impl Tempdir {
291	    /// Creates a directory at the path and auto-cleans it.
292	    fn create(path: PathBuf) -> std::io::Result<Self> {
293	        std::fs::create_dir_all(&path)?;
294	        Ok(Self(path))
295	    }
296	}
297	
298	#[cfg(feature = "universe-packages")]
299	impl Drop for Tempdir {
300	    fn drop(&mut self) {
301	        _ = std::fs::remove_dir_all(&self.0);
302	    }
303	}
304	
305	#[cfg(feature = "universe-packages")]
306	impl AsRef<Path> for Tempdir {
307	    fn as_ref(&self) -> &Path {
308	        &self.0
309	    }
310	}
311	
312	/// Serves packages from the Typst Universe registry.
313	///
314	/// There is no standardized registry protocol. This is merely designed to work
315	/// with the official Typst Universe package registry.
316	#[cfg(feature = "universe-packages")]
317	pub struct UniversePackages {
318	    /// The URL of the registry.
319	    url: String,
320	    /// A downloader with which we can download from the registry.
321	    downloader: Box<dyn Downloader>,
322	    /// The package index.
323	    index: OnceCell<Box<[serde_json::Value]>>,
324	}
325	
326	#[cfg(feature = "universe-packages")]
327	impl UniversePackages {
328	    /// The namespace from which Typst Universe serves packages.
329	    pub const NAMESPACE: &str = "preview";
330	
331	    /// Creates a new handle for interacting with the primary official registry
332	    /// at `https://packages.typst.org`.
333	    pub fn new(downloader: impl Downloader) -> Self {
334	        Self::with_url(downloader, "https://packages.typst.org")
335	    }
336	
337	    /// Creates a new handle which serves packages from an alternative mirror.
338	    pub fn with_url(downloader: impl Downloader, url: impl Into<String>) -> Self {
339	        Self {
340	            url: url.into(),
341	            downloader: Box::new(downloader),
342	            index: OnceCell::new(),
343	        }
344	    }
345	
346	    /// Returns the registry's URL.
347	    pub fn url(&self) -> &str {
348	        &self.url
349	    }
350	
351	    /// Attempts to download a package from the registry.
352	    ///
353	    /// Will invoke the downloader with the `spec` as the key.
354	    pub fn package(
355	        &self,
356	        spec: &PackageSpec,
357	    ) -> PackageResult<tar::Archive<impl Read + use<>>> {
358	        if spec.namespace != Self::NAMESPACE {
359	            return Err(PackageError::NotFound(spec.clone()));
360	        }
361	
362	        let url = format!(
363	            "{}/{}/{}-{}.tar.gz",
364	            self.url,
365	            Self::NAMESPACE,
366	            spec.name,
367	            spec.version,
368	        );
369	
370	        match self.downloader.download(spec, &url) {
371	            Ok(data) => {
372	                let decompressed = flate2::read::GzDecoder::new(Cursor::new(data));
373	                Ok(tar::Archive::new(decompressed))
374	            }
375	            Err(err) if err.kind() == std::io::ErrorKind::NotFound => {
376	                Err(match self.latest_version(&spec.versionless()) {
377	                    Ok(version) => PackageError::VersionNotFound(spec.clone(), version),
378	                    Err(_) => PackageError::NotFound(spec.clone()),
379	                })
380	            }
381	            Err(err) => Err(PackageError::NetworkFailed(Some(eco_format!("{err}")))),
382	        }
383	    }
384	
385	    /// Attempts to determine the latest version of a package.
386	    ///
387	    /// Will invoke the downloader with the key `"package index"`.
388	    pub fn latest_version(
389	        &self,
390	        spec: &VersionlessPackageSpec,
391	    ) -> StrResult<PackageVersion> {
392	        /// Minimal information required about a package to determine its latest
393	        /// version.
394	        #[derive(Deserialize)]
395	        struct MinimalPackageInfo {
396	            name: String,
397	            version: PackageVersion,
398	        }
399	
400	        if spec.namespace != Self::NAMESPACE {
401	            bail!(
402	                "failed to determine latest version \
403	                 (an index is only available for the `{}` namespace)",
404	                Self::NAMESPACE
405	            )
406	        }
407	
408	        self.index()?
409	            .iter()
410	            .filter_map(|value| MinimalPackageInfo::deserialize(value).ok())
411	            .filter(|package| package.name == spec.name)
412	            .map(|package| package.version)
413	            .max()
414	            .ok_or_else(|| eco_format!("failed to find package {spec}"))
415	    }
416	
417	    /// Downloads the package index for the default namespace from the registry
418	    /// or serves it from its in-memory cache.
419	    ///
420	    /// For compatibility, the individual entries are left unserialized. This
421	    /// way, packages that cannot be deserialized with this compiler version can
422	    /// be skipped instead of failing completely.
423	    ///
424	    /// The index format of the official package registry is not specified or
425	    /// stabilized and may be changed at any time.
426	    fn index(&self) -> StrResult<&[serde_json::Value]> {
427	        self.index
428	            .get_or_try_init(|| {
