196	/// Loads Adobe fonts available on the system. Only supported on Windows and
197	/// macOS.
198	///
199	/// This is permissible as per Clause 3.1 (A) of the
200	/// [Adobe Fonts Service Product Specific Terms][terms].
201	///
202	/// [terms]: https://wwwimages2.adobe.com/content/dam/cc/en/legal/servicetou/Adobe-Fonts-Product-Specific-Terms-en_US-20241007.pdf
203	#[cfg(all(feature = "scan-fonts", any(target_os = "windows", target_os = "macos")))]
204	fn load_adobe_fonts(db: &mut fontdb::Database) {
205	    let Some(data) = dirs::data_dir() else { return };
206	    let base = data.join("Adobe");
207	
208	    let prefix = if cfg!(target_os = "macos") { "." } else { "" };
209	    let subdirs = [
210	        PathBuf::from("CoreSync")
211	            .join("plugins")
212	            .join("livetype")
213	            .join(format!("{prefix}r")),
214	        PathBuf::from(format!("{prefix}User Owned Fonts")),
215	    ];
216	
217	    for subdir in subdirs {
218	        let Ok(entries) = fs::read_dir(base.join(subdir)) else { continue };
219	        for entry in entries.flatten() {
220	            // Adobe fonts are stored as files (directories are skipped).
221	            let Ok(metadata) = entry.metadata() else { continue };
222	            if metadata.is_file() {
223	                db.load_font_file(entry.path()).ok();
224	            }
225	        }
226	    }
227	}
