291	/// Manages progress reporting for downloads.
292	pub trait ProgressReporter {
293	    /// Invoked when a download is started.
294	    fn start(&mut self, progress: &Progress);
295	
296	    /// Invoked repeatedly while a download is ongoing.
297	    fn update(&mut self, progress: &Progress);
298	
299	    /// Invoked when a download is finished.
300	    fn finish(&mut self, progress: &Progress);
301	}
