303	/// The current progress of a download.
304	#[derive(Debug)]
305	pub struct Progress {
306	    /// The download starting instant.
307	    pub start_time: Instant,
308	    /// The expected amount of bytes to download, `None` if the response header
309	    /// was not set.
310	    pub content_len: Option<usize>,
311	    /// The total amount of downloaded bytes until now.
312	    pub downloaded: usize,
313	    /// A backlog of the amount of downloaded bytes for each bucket.
314	    pub samples: VecDeque<usize>,
315	    /// The duration of each bucket (in samples).
316	    pub period: Duration,
317	}
318	
319	impl Display for Progress {
320	    /// Formats several download statistics for display.
321	    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
322	        let len = self.samples.len();
323	        let sum: usize = self.samples.iter().sum();
324	        let bytes_per_period = sum.checked_div(len).or(self.content_len).unwrap_or(0);
325	
326	        let frequency: usize = Duration::from_secs(1)
327	            .as_nanos()
328	            .checked_div(self.period.as_nanos())
329	            .and_then(|s| s.try_into().ok())
330	            .unwrap_or(1);
331	        let bytes_per_sec = bytes_per_period * frequency;
332	
333	        match self.content_len {
334	            Some(content_len) => {
335	                let ratio = self.downloaded as f64 / content_len as f64;
336	                let remaining_bytes = content_len - self.downloaded;
337	                let remaining_buckets: u32 = remaining_bytes
338	                    .checked_div(bytes_per_period)
339	                    .and_then(|c| c.try_into().ok())
340	                    .unwrap_or(0);
341	
342	                let eta = self.period * remaining_buckets;
343	
344	                write!(
345	                    f,
346	                    "{downloaded} / {total} ({percent:3.0} %), {bytes}/s, ETA: {eta}",
347	                    downloaded = format_byte_unit(self.downloaded),
348	                    total = format_byte_unit(content_len),
349	                    percent = 100.0 * ratio,
350	                    bytes = format_byte_unit(bytes_per_sec),
351	                    eta = format_seconds(eta),
352	                )
353	            }
354	
355	            None => write!(
356	                f,
357	                "{downloaded}, {bytes}/s",
358	                downloaded = format_byte_unit(self.downloaded),
359	                bytes = format_byte_unit(bytes_per_sec),
360	            ),
361	        }
362	    }
363	}
364	
365	/// Format a given size as a unit of bytes.
366	fn format_byte_unit(size: usize) -> impl Display {
367	    const KI: f64 = 1024.0;
368	    const MI: f64 = KI * KI;
369	    const GI: f64 = KI * KI * KI;
370	
371	    let size = size as f64;
372	
373	    typst_utils::display(move |f| {
374	        if size >= GI {
375	            write!(f, "{:5.1} GiB", size / GI)
376	        } else if size >= MI {
377	            write!(f, "{:5.1} MiB", size / MI)
378	        } else if size >= KI {
379	            write!(f, "{:5.1} KiB", size / KI)
380	        } else {
381	            write!(f, "{size:3} B")
382	        }
383	    })
384	}
385	
386	/// Formats a duration with second precision.
387	fn format_seconds(duration: Duration) -> impl Display {
388	    typst_utils::display(move |f| write!(f, "{} s", duration.as_secs()))
389	}
390	
391	// Acknowledgment:
392	// The `RemoteReader` is closely modeled after rustup's `DownloadTracker`.
393	// https://github.com/rust-lang/rustup/blob/master/src/cli/download_tracker.rs
394	
395	/// Keep track of this many download speed samples.
396	const SAMPLES: usize = 25;
397	
398	/// A wrapper around [`ureq::Response`] that reads the response body in chunks
399	/// over a websocket and reports its progress.
400	struct ProgressReader<'p> {
401	    /// The reader returned by the [`ureq::Response`].
402	    reader: Box<dyn Read>,
403	    /// The download state, holding download metadata for progress reporting.
404	    state: Progress,
405	    /// The instant at which progress was last reported.
406	    last_progress: Option<Instant>,
407	    /// A trait object used to report download progress.
408	    progress: &'p mut dyn ProgressReporter,
409	}
410	
411	impl<'p> ProgressReader<'p> {
412	    /// Wraps a [`ureq::Response`] and prepares it for downloading.
413	    ///
414	    /// The 'Content-Length' header is used as a size hint for read
415	    /// optimization, if present.
416	    fn new(
417	        content_len: Option<usize>,
418	        reader: Box<dyn Read>,
419	        period: Duration,
420	        progress: &'p mut dyn ProgressReporter,
421	    ) -> Self {
422	        Self {
423	            reader,
424	            last_progress: None,
425	            state: Progress {
426	                content_len,
427	                downloaded: 0,
428	                samples: VecDeque::with_capacity(SAMPLES),
429	                start_time: Instant::now(),
430	                period,
431	            },
432	            progress,
433	        }
434	    }
435	
436	    /// Download the body's content as raw bytes while reporting download
437	    /// progress.
438	    fn download(mut self) -> io::Result<Vec<u8>> {
439	        let mut buffer = vec![0; 8192];
440	        let mut data = match self.state.content_len {
441	            Some(content_len) => Vec::with_capacity(content_len),
442	            None => Vec::with_capacity(8192),
443	        };
444	
445	        self.progress.start(&self.state);
446	
447	        let mut downloaded_this_period = 0;
448	        loop {
449	            let read = match self.reader.read(&mut buffer) {
450	                Ok(0) => break,
451	                Ok(n) => n,
452	                // If the data is not yet ready but will be available eventually
453	                // keep trying until we either get an actual error, receive data
454	                // or an Ok(0).
455	                Err(ref e) if e.kind() == ErrorKind::Interrupted => continue,
456	                Err(e) => return Err(e),
457	            };
458	
459	            data.extend(&buffer[..read]);
460	
461	            let last_printed = match self.last_progress {
462	                Some(prev) => prev,
463	                None => {
464	                    let current_time = Instant::now();
465	                    self.last_progress = Some(current_time);
466	                    current_time
467	                }
468	            };
469	            let elapsed = Instant::now().saturating_duration_since(last_printed);
470	
471	            downloaded_this_period += read;
472	            self.state.downloaded += read;
473	
474	            if elapsed >= self.state.period {
475	                if self.state.samples.len() == SAMPLES {
476	                    self.state.samples.pop_back();
477	                }
478	
479	                self.state.samples.push_front(downloaded_this_period);
480	                downloaded_this_period = 0;
481	
482	                self.progress.update(&self.state);
483	                self.last_progress = Some(Instant::now());
484	            }
485	        }
486	
487	        self.progress.finish(&self.state);
488	        Ok(data)
489	    }
490	}
