160	#[cfg(feature = "system-downloader")]
161	impl Downloader for SystemDownloader {
162	    fn stream(
163	        &self,
164	        _: &dyn Any,
165	        url: &str,
166	    ) -> io::Result<(Option<usize>, Box<dyn Read>)> {
167	        let mut builder = ureq::AgentBuilder::new();
168	        let mut tls = TlsConnector::builder();
169	
170	        // Set user agent.
171	        builder = builder.user_agent(&self.user_agent);
172	
173	        // Get the network proxy config from the environment and apply it.
174	        if let Some(proxy) = env_proxy::for_url_str(url)
175	            .to_url()
176	            .and_then(|url| ureq::Proxy::new(url).ok())
177	        {
178	            builder = builder.proxy(proxy);
179	        }
180	
181	        // Apply a custom CA certificate if present.
182	        if let Some(cert) = self.cert() {
183	            tls.add_root_certificate(cert?.clone());
184	        }
185	
186	        // Configure native TLS.
187	        let connector = tls.build().map_err(io::Error::other)?;
188	        builder = builder.tls_connector(Arc::new(connector));
189	
190	        let response = builder.build().get(url).call().map_err(|err| match err {
191	            ureq::Error::Status(404, _) => io::Error::new(io::ErrorKind::NotFound, err),
192	            err => io::Error::other(err),
193	        })?;
194	
195	        let content_len: Option<usize> = response
196	            .header("Content-Length")
197	            .and_then(|header| header.parse().ok());
198	
199	        Ok((content_len, response.into_reader()))
200	    }
201	}
