15	pub fn downloader() -> impl Downloader {
16	    let user_agent = format!("typst/{}", typst::utils::version().raw());
17	    let system = match ARGS.cert.clone() {
18	        None => SystemDownloader::new(user_agent),
19	        Some(cert) => SystemDownloader::with_cert_path(user_agent, cert),
20	    };
21	
22	    ProgressDownloader::new(system, |key| {
23	        let name = if let Some(spec) = key.downcast_ref::<PackageSpec>() {
24	            Some(eco_format!("{spec}"))
25	        } else if let Some(&s @ "release") = key.downcast_ref::<&str>() {
26	            Some(s.into())
27	        } else {
28	            None
29	        };
30	        PrintProgress(name)
31	    })
32	}
