34	/// Prints download progress by writing `downloading {0}` followed by repeatedly
35	/// updating the last terminal line.
36	struct PrintProgress(Option<EcoString>);
37	
38	impl ProgressReporter for PrintProgress {
39	    fn start(&mut self, progress: &Progress) {
40	        if let Some(name) = &self.0 {
41	            let styles = term::Styles::default();
42	            let mut out = terminal::out();
43	            _ = out.set_color(&styles.header_help);
44	            _ = write!(out, "downloading");
45	            _ = out.reset();
46	            _ = writeln!(out, " {name}");
47	            _ = writeln!(out);
48	        }
49	        self.update(progress);
50	    }
51	
52	    fn update(&mut self, progress: &Progress) {
53	        if self.0.is_some() {
54	            let mut out = terminal::out();
55	            _ = out.clear_last_line();
56	            _ = writeln!(out, "{progress}");
57	        }
58	    }
59	
60	    fn finish(&mut self, progress: &Progress) {
61	        self.update(progress);
62	    }
63	}
